    index=ROOT/('r/lazy4-a-v1/provider/runtime-index.json' if NODE=='node-a' else 'r/lazy4-b-v1/provider/runtime-index.json')
    index_sha=digest(own(index,2*1024**2)) if VARIANT=='lazy' else None
    if index_sha:pins[str(index)]=index_sha
